<?php namespace App\Http\Controllers\Api\Dashboard; use App\Http\Controllers\Controller; use App\Models\{InventoryCount,InventoryProduct,WarehouseStock,StockMovement}; use App\Services\DocumentNumberService; use Illuminate\Http\Request; use Illuminate\Support\Facades\DB; class InventoryCountController extends Controller {public function index(Request $r){return response()->json(InventoryCount::with(['warehouse','lines.product'])->latest()->paginate($r->integer('per_page',25)));} public function store(Request $r,DocumentNumberService $nums){$v=$r->validate(['warehouse_id'=>'required|exists:warehouses,id','notes'=>'nullable|string','lines'=>'required|array|min:1','lines.*.inventory_product_id'=>'required|exists:inventory_products,id','lines.*.counted_quantity'=>'required|integer|min:0']);return DB::transaction(function()use($v,$nums,$r){$c=InventoryCount::create(['count_number'=>$nums->next('inventory_count','INV'),'warehouse_id'=>$v['warehouse_id'],'status'=>'draft','count_date'=>now()->toDateString(),'notes'=>$v['notes']??null,'created_by'=>$r->user()->id]);foreach($v['lines'] as $x){$ws=WarehouseStock::firstOrCreate(['warehouse_id'=>$v['warehouse_id'],'inventory_product_id'=>$x['inventory_product_id']],['quantity'=>0,'reserved_quantity'=>0]);$c->lines()->create(['inventory_product_id'=>$x['inventory_product_id'],'system_quantity'=>$ws->quantity,'counted_quantity'=>$x['counted_quantity'],'difference'=>$x['counted_quantity']-$ws->quantity]);}return response()->json($c->load(['warehouse','lines.product']),201);});} public function validateCount(InventoryCount $count){abort_unless($count->status==='draft',422,'Inventaire deja traite.');return DB::transaction(function()use($count){$count->load('lines');foreach($count->lines as $line){$ws=WarehouseStock::lockForUpdate()->firstOrCreate(['warehouse_id'=>$count->warehouse_id,'inventory_product_id'=>$line->inventory_product_id],['quantity'=>0,'reserved_quantity'=>0]);$before=$ws->quantity;$ws->update(['quantity'=>$line->counted_quantity]);$p=InventoryProduct::find($line->inventory_product_id);$p->update(['stock_quantity'=>max(0,$p->stock_quantity+$line->difference)]);if($line->difference)StockMovement::create(['inventory_product_id'=>$line->inventory_product_id,'warehouse_id'=>$count->warehouse_id,'type'=>'adjustment','quantity'=>$line->difference,'stock_before'=>$before,'stock_after'=>$line->counted_quantity,'reference'=>$count->count_number,'reason'=>'Inventaire physique']);}$count->update(['status'=>'validated']);return response()->json($count->fresh(['warehouse','lines.product']));});}}